#!/bin/bash
# deployment_checklist.sh
# PREDATOR PAIM Optimization Deployment Checklist
# Run this before pushing to GitHub

echo \"PREDATOR PAIM OPTIMIZATION DEPLOYMENT CHECKLIST\"
echo \"\"\n# Color codes\nRED='\\033[0;31m'\nGREEN='\\033[0;32m'\nYELLOW='\\033[1;33m'\nNC='\\033[0m' # No Color\n\nPASS=0\nFAIL=0\n\n# Function to check\ncheck() {\n    if [ $? -eq 0 ]; then\n        echo -e \"${GREEN}✓${NC} $1\"\n        ((PASS++))\n    else\n        echo -e \"${RED}✗${NC} $1\"\n        ((FAIL++))\n    fi\n}\n\necho \"[1/5] Checking Python syntax...\"\npython3 -m py_compile core/paim_engine.py core/constants.py run_engine.py 2>/dev/null\ncheck \"Python files compile\"\n\necho \"\"\necho \"[2/5] Checking imports...\"\npython3 -c \"from core.paim_engine import _normalize_team; from core.constants import GLOBAL_TIMEOUT; print('OK')\" 2>/dev/null\ncheck \"Imports resolve correctly\"\n\necho \"\"\necho \"[3/5] Verifying constants...\"\npython3 -c \"\nfrom core.constants import (\n    ELITE_EDGE, MIN_STAKE, BANKROLL_REF, MAX_EDGE,\n    DELAY_XBET_MIN, DELAY_XBET_MAX, DELAY_GEMINI_RATE,\n    DELAY_DB_RETRY, MAX_DB_RETRIES, GLOBAL_TIMEOUT\n)\nassert ELITE_EDGE == 2.5\nassert GLOBAL_TIMEOUT == 540\nassert MAX_DB_RETRIES == 3\nprint('OK')\n\" 2>/dev/null\ncheck \"Constants properly defined\"\n\necho \"\"\necho \"[4/5] Checking cache function...\"\npython3 -c \"\nfrom core.paim_engine import _normalize_team\nassert hasattr(_normalize_team, 'cache_info')\nassert hasattr(_normalize_team, 'cache_clear')\nprint('OK')\n\" 2>/dev/null\ncheck \"Team normalization is cached\"\n\necho \"\"\necho \"[5/5] Checking git status...\"\ngit status --porcelain | grep -q \"??.*OPTIMIZATION\" && echo \"Documentation files detected\" || echo \"git status ok\"\ncheck \"Git tracked properly\"\n\necho \"\"\necho \"════════════════════════════════════════════════════════════════\"\necho \"\"\n\nif [ $FAIL -eq 0 ]; then\n    echo -e \"${GREEN}✅ ALL CHECKS PASSED - Ready to deploy!${NC}\"\n    echo \"\"\n    echo \"Next steps:\"\n    echo \"  1. git add -A\"\n    echo \"  2. git commit -m 'chore: deploy PAIM optimizations (v8.5+)'\"\n    echo \"  3. Enable PREDATOR_DEBUG=1 in GitHub Actions\"\n    echo \"  4. Push and monitor first scan\"\n    exit 0\nelse\n    echo -e \"${RED}❌ $FAIL check(s) failed - do not deploy${NC}\"\n    exit 1\nfi\n"